import java.io.*;import java.util.*;public class Solution {static int cuts = 0;static List<List<Integer>> adj;static int[] subtreeSize;static int evenForest(int t_nodes, int t_edges, List<Integer> t_from, List<Integer> t_to) {adj = new ArrayList<>(t_nodes + 1);for (int i = 0; i <= t_nodes; i++) adj.add(new ArrayList<Integer>());for (int i = 0; i < t_edges; i++) {adj.get(t_from.get(i)).add(t_to.get(i));adj.get(t_to.get(i)).add(t_from.get(i));}subtreeSize = new int[t_nodes + 1];cuts = 0;dfs(1, -1);return cuts;}private static int dfs(int u, int p) {int size = 1;for (int v : adj.get(u)) {if (v != p) {int childSize = dfs(v, u);if (childSize % 2 == 0) {cuts++;} else {size += childSize;}}}subtreeSize[u] = size;return size;}public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String[] tNodesEdges = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int tNodes = Integer.parseInt(tNodesEdges[0]);int tEdges = Integer.parseInt(tNodesEdges[1]);List<Integer> tFrom = new ArrayList<>();List<Integer> tTo = new ArrayList<>();for (int i = 0; i < tEdges; i++) {String[] tFromTo = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");tFrom.add(Integer.parseInt(tFromTo[0]));tTo.add(Integer.parseInt(tFromTo[1]));}int res = evenForest(tNodes, tEdges, tFrom, tTo);bufferedWriter.write(String.valueOf(res));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}